},
}
                switch (iter.c) {
-1 => {
return try self.addDefaultError("Unexpected end of file");
},
0...127 => {
_ = ((buf.append(@as(u8, @intCast(iter.c)))) catch unreachable);
},
else => {
var part: [4]u8 = undefined;
                _ = &part;
                const len = strings.encodeWTF8Rune((&part), iter.c);
                _ = try buf.appendSlice(part[0..len]);
},
}
            }
    }

pub fn expected(self: *Lexer, token: TokenType) !void {
            _ = try self.expectedString(@as([]const u8, @tagName(token)));
    }

pub fn unexpected(self: *Lexer) !void {
            const found = finder: {
            self.start = @min(self.start, self.end);
            if ((self.start == self.source.contents.len)) {
                break :finder "end of file";
            } else {
                break :finder self.raw();
            }
};
            _ = try self.addRangeError(self.range(), "Unexpected {s}", .{ found });
    }

pub fn expectedString(self: *Lexer, text: []const u8) !void {
            const found = finder: {
            if ((self.source.contents.len != self.start)) {
                break :finder self.raw();
            } else {
                break :finder "end of file";
            }
};
            _ = try self.addRangeError(self.range(), "Expected {s} but found {s}", .{ text, found });
    }

pub fn range(self: Lexer) logger.Range {
            return logger.Range{ .loc = logger.usize2Loc(self.start), .len = std.math.lossyCast(i32, (self.end - self.start)) };
    }

pub fn init(log: *logger.Log, source: logger.Source, allocator: std.mem.Allocator, redact_logs: bool) !Lexer {
            var lex = Lexer{ .log = log, .source = source, .prev_error_loc = logger.Loc.Empty, .allocator = allocator, .should_redact_logs = redact_logs };
            _ = &lex;
            _ = lex.step();
            _ = try lex.next();
            return lex;
    }

pub inline fn toString(self: *Lexer, loc_: logger.Loc) js_ast.Expr {
            if (self.string_literal_is_ascii) {
                return js_ast.Expr.init(js_ast.E.String, js_ast.E.String{ .data = self.string_literal_slice }, loc_);
            }
            return js_ast.Expr.init(js_ast.E.String, .{ .data = self.string_literal_slice }, loc_);
    }

pub fn raw(self: *const Lexer) []const u8 {
            return self.source.contents[self.start..self.end];
    }
    pub const T = TokenType;
};

const CodePoint = bun.CodePoint;
const js_ast = bun.ast;
const logger = bun.logger;
const strings = bun.strings;

pub fn isIdentifierPart(code_point: CodePoint) bool {
        return (switch (code_point) {
48...57, 97...122, 65...90, '$', '_', '-', ':' => true,
else => false,
});
}

pub fn isLatin1Identifier(comptime Buffer: type, name: Buffer) bool {
        if ((name.len == 0)) {
            return false;
        }
        switch (name[0]) {
97...122, 65...90, '$', 49...57, '_', '-' => {

},
else => {
return false;
},
}
        if ((name.len > 0)) {
            for (name[1..]) |c| {
                _ = &c;
                switch (c) {
48...57, 97...122, 65...90, '$', '_', '-' => {

},
else => {
return false;
},
}
            }
        }
        return true;
}

pub inline fn float64(num: anytype) f64 {
        const f: f64 = @floatFromInt(num);
        return f;
}
